  &DefaultButton;




function dir$cdtt20(p){
  this.constructor(p);
}
dir$cdtt20.prototype = new DirEvent();
dir$cdtt20.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
}
dir$cdtt20.prototype.afterInit = function(renderType){
  var p = this._dir;
  var exp = {
    t_tt_nt: ['#t_tt_nt', '[t_tt_nt0]-[t_da_tt_nt]'],
    t_tt: ['#t_tt', '[t_tt0]-[t_da_tt]'],
    t_tt_tg: ['#t_tt', '[t_tt_nt]*[ty_gia]'],
    t_tt0_tg: ['#t_tt0', '[t_tt_nt0]*[ty_gia]'],
    t_da_tt_tg: ['#t_da_tt', '[t_da_tt_nt]*[ty_gia]']
  }
  p.applyExpressionForm(exp, true);
  //console.log(JSON.stringify(p.options.FomulaApplied)); 

  p.options.FCColumns = {FC: ['t_tt_nt0', 't_da_tt_nt', 't_tt_nt'], BC: ['t_tt0', 't_da_tt', 't_tt']};

  var oldTG = '', oTG = p.jObject('ma_nt'); //Neu ty gia thay doi
  oTG.focus(function(){ oldTG = oTG.fval(); }).blur(function(){ if (oldTG != oTG.fval()) onExRateChanged(oTG, p);});
  p.applyFCColumns();
  p.setFCHidden(oTG.fval());
}

dir$cdtt20.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir;
  switch (id) {
    case 'ok':
      break;
    default:
      break;
  }
  return true;
}


dir$cdtt20.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ty_gia':
      p.calcExpressionAll(p.options, 'ty_gia');
      break;
    case 'ma_kh':
      p.request('Customer', '', ['ma_kh', 'ngay_ct', 'ma_nt']);
      break;
    default:
      break;
  }
}
function onExRateChanged(o, p) {
  p.setFCHidden(o.fval());
  p.request('GetExRate', '', ['ma_nt', 'ngay_ct'], function(){
    p.calcExpressionAll(p.options, 'ty_gia');
  });
}

function dir$cdtt20DisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=6],[value=7],[value=9]").remove();
}





