declare @ma_nvbh varchar(32), @ten_nvbh nvarchar(256), @ma_dc varchar(32), @ten_dc nvarchar(256), @ong_ba nvarchar(256)
select @ma_nvbh = a.ma_nvbh, @ten_nvbh = b.ten_nvbh, @ong_ba = nguoi_lh from dmkh a join dmnvbh b on a.ma_nvbh = b.ma_nvbh where ma_kh = @ma_kh
if 1 = (select count(1) from dmdc where ma_kh = @ma_kh) select @ma_dc = ma_dc, @ten_dc = ten_dc from dmdc where ma_kh = @ma_kh
select isnull(@ma_nvbh, '') as [!ma_nvbh], isnull(@ten_nvbh, '') as [!ten_nvbh], isnull(@ma_dc, '') as [!ma_dc], isnull(@ten_dc, '') as [!ten_dc], isnull(@ong_ba, '') as [!ong_ba]







